    fun categoryLabel(id: String): String = categories.firstOrNull { it.id == id }?.label.orEmpty()

    /** Igual a `searchMedications()` da web: o nome contém o texto, sem diferenciar maiúsculas. */
    fun search(query: String, category: String = ""): List<LibraryMedication> {
        val q = query.trim().lowercase()
        return medications.filter { med ->
            (q.isEmpty() || med.name.lowercase().contains(q)) &&
                (category.isEmpty() || med.category == category)
        }
    }
